from pathlib import Path
import base64,json
import sys
base=Path(__file__).resolve().parents[1]
js=(base/'assets/editor.js').read_text()
start=js.index('async function api(');end=js.index('\nfunction status',start)
adapter=r'''const storageKey='SHEM-DOK-preview-v1';
function readDB(){const value=localStorage.getItem(storageKey);return value?JSON.parse(value):{next:7001,docs:{},requests:{},settings:{defaults:Object.fromEntries(['business','businessId','address','phone','email','title','vat','supply1','supply2'].map(k=>[k,seed()[k]])),auto:false}}}
function writeDB(db){localStorage.setItem(storageKey,JSON.stringify(db))}
const clone=x=>JSON.parse(JSON.stringify(x));
function validate(d){validateDocument();if(d.method==='paypal'){d.last4='';d.brand='';d.installments=''}else d.paypalEmail='';}
async function api(path,body){if(body&&navigator.locks)return navigator.locks.request(storageKey,()=>localApi(path,body));return localApi(path,body)}
function localApi(path,body){const db=readDB();if(path==='state')return{settings:clone(db.settings),pdfReady:true,woocommerce:false};if(path==='settings'){db.settings=clone({...body,auto:false});writeDB(db);return clone(db.settings)}if(path.startsWith('documents?')){const page=Number(new URLSearchParams(path.split('?')[1]).get('page'))||1;const rows=Object.values(db.docs).sort((a,b)=>b.id-a.id).map(r=>({...r,customer:r.document.customer,total:r.total}));return{rows:rows.slice((page-1)*30,page*30),total:rows.length,page}}if(path==='issue'){if(db.requests[body.requestId]){const id=db.requests[body.requestId];if(!db.docs[id])throw Error('המסמך נמחק. יש לפתוח מסמך חדש');return{...clone(db.docs[id]),existing:true}}validate(body.document);const id=db.next++;const row={id,version:1,document:clone(body.document),total:totals().gross,updated_at:new Date().toISOString().slice(0,19).replace('T',' ')};db.docs[id]=row;db.requests[body.requestId]=id;writeDB(db);return clone(row)}const m=path.match(/^document\/(\d+)(?:\/(save|delete))?$/);if(m){const row=db.docs[m[1]];if(!row)throw Error('המסמך אינו קיים');if(!m[2])return clone(row);if(row.version!==body.version)throw Error('המסמך עודכן בחלון אחר. יש לפתוח אותו שוב מהארכיון');if(m[2]==='delete'){delete db.docs[m[1]];writeDB(db);return{deleted:true}}validate(body.document);row.document=clone(body.document);row.total=totals().gross;row.version++;row.updated_at=new Date().toISOString().slice(0,19).replace('T',' ');writeDB(db);return clone(row)}throw Error('חיבור WooCommerce אינו פעיל בקובץ התצוגה')}
async function printLocal(id){const row=readDB().docs[id];if(!row)throw Error('המסמך אינו קיים');const previous=doc,previousCurrent=current;doc=clone(row.document);current={id:row.id,version:row.version};preview();const markup=root.querySelector('#sd-paper').outerHTML;doc=previous;current=previousCurrent;preview();const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:1px;height:1px;bottom:0;left:0;border:0';frame.title='הדפסת מסמך';document.body.append(frame);frame.onload=async()=>{await Promise.all([...frame.contentDocument.images].map(img=>img.decode?.().catch(()=>{})));frame.contentWindow.focus();frame.contentWindow.print();setTimeout(()=>frame.remove(),60000)};frame.srcdoc='<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><title>SHEM '+id+'</title><style>'+document.getElementById('app-css').textContent+' body{margin:0;background:white}#shem-dok-root{margin:0;background:white;min-height:0}#sd-paper{width:100%;min-height:0;margin:0;box-shadow:none} @page{size:A4;margin:12mm}thead{display:table-header-group}tr,.sd-section{break-inside:avoid}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}</style></head><body><div id="shem-dok-root">'+markup+'</div></body></html>';}
'''
js=js[:start]+adapter+js[end:]
js=js.replace('location.href=d.downloadUrl','await printLocal(d.id)').replace('location.href=data.downloadUrl','await printLocal(data.id)')
js=js.replace('ברירות המחדל נשמרו בשרת.','ברירות המחדל נשמרו בדפדפן זה.')
js=js.replace('ההפקה מתבצעת בשרת. הודעות ללקוח אינן נשלחות מהמערכת.','בקובץ התצוגה החיבור לחנות וההפקה האוטומטית אינם פעילים.')
js=js.replace('layout();newDocument();','layout();root.querySelectorAll(\'#sd-order,#sd-auto,[data-action="import"]\').forEach(el=>el.disabled=true);newDocument();')
css=(base/'assets/editor.css').read_text()
logo='data:image/png;base64,'+base64.b64encode((base/'assets/logo.png').read_bytes()).decode()
html='''<!doctype html><html lang="he" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>SHEM DOK — תצוגה לבדיקה</title><style id="app-css">'''+css+'''\nbody{margin:0}#shem-dok-root{margin:0}.local-notice{padding:12px 24px;background:#fff8e9;color:#493d25;font:14px Arial;line-height:1.7}.local-notice strong{color:#111}@media print{.local-notice{display:none}}</style></head><body><div class="local-notice"><strong>SHEM DOK · גרסת בדיקה מקומית</strong> — עריכה, ברירות מחדל וארכיון נשמרים בדפדפן במחשב זה. אין חיבור לחנות. להפקת PDF בחרו ״שמירה כ־PDF״ בחלון ההדפסה, ובטלו ״כותרות עליונות ותחתונות״. מומלץ להוריד גיבוי למסמכים חשובים. ביטול ההדפסה אינו מוחק מסמך שכבר הוקצה לו מספר.</div><div id="shem-dok-root"></div><script>window.SHEM_DOK='''+json.dumps({'logo':logo},ensure_ascii=False)+''';</script><script>'''+js+'''</script></body></html>'''
destination=Path(sys.argv[1]) if len(sys.argv)>1 else Path.cwd()/'SHEM-DOK-preview.html'
destination.write_text(html)
print('Created preview:',len(html.encode()),'bytes')
